def name(self, cell=None):
        rec = self.getRecord()
        if cell is None:
            cell = rec['cell']
        if cell is None:
            return ""
        name = cell.shortName()
        if rec['holding'] < -.04:
            name = name + "_excitatory"
        elif rec['holding'] >= -.01:
            name = name + "_inhibitory"
        return name

def getCurrentDir(self):
        if self.currentDir is None:
            raise Exception("CurrentDir has not been set!")
        return self.currentDir

